<template>
  <view><TutorialOnlyGate v-if="tutorialFirst" /><view v-else><view><SiteHeader active="events"/><view class="wrap"><view class="fde-feature">
  <button class="fde-trigger" role="button" tabindex="0" :aria-expanded="fdeOpen" aria-controls="fde-details" @click="fdeOpen=!fdeOpen" @keydown.enter.prevent="fdeOpen=!fdeOpen" @keydown.space.prevent="fdeOpen=!fdeOpen">
    <image class="fde-thumb" src="/static/assets/fde-cover.jpg" mode="aspectFit" />
    <view class="fde-preview"><text class="fde-kicker">{{ conferenceLabel }} · FDE 实战与线下交流</text><text class="fde-title">AI航海家FDE大会</text><text class="fde-meta">{{ conference ? formatDate(conference.startTime) + ' · ' + (conference.city || '北京') + ' ' + (conference.district || '') : '活动时间与地点以报名资料为准' }}</text><text class="fde-status">{{ conferenceStatus }}</text><text class="fde-teaser">{{registrationLabel === '查看大会报名图' ? '把 AI 做进真实业务，和同行聊获客、交付与协作。' : '回顾企业 AI 落地话题与同行交流资料。'}}</text></view>
    <view class="fde-toggle">{{ fdeOpen ? '收起专题' : '展开查看' }} <text>{{ fdeOpen ? '⌃' : '⌄' }}</text></view>
  </button>
  <view v-if="fdeOpen" id="fde-details" class="fde-details">
    <view class="fde-details-copy"><text class="fde-detail-label">真实业务 · 同行交流</text><text class="fde-detail-title">下一站，FDE。<br/>把 AI 做进真实生意。</text><text class="fde-body">{{registrationLabel === '查看大会报名图' ? '企业 AI 落地的机会，藏在真实业务问题里。想入局，或已在做，都可以来现场和同行聊获客、交付与协作。' : '企业 AI 落地的机会，藏在真实业务问题里。回顾大会资料，了解同行关于获客、交付与协作的讨论。'}}</text><text class="fde-highlights">同行交流　·　实战拆解　·　资源连接</text><text class="fde-program">7 位主嘉宾 · 20 多场主题夜话</text><view v-if="conference" class="fde-info"><text>{{ formatDate(conference.startTime) }}</text><text>{{ conference.city }} · {{ conference.district }}</text><text v-if="conference.submitEnd">{{Number(conference.submitEnd)*1000 <= now ? '报名已截止' : '报名截止 ' + formatDate(conference.submitEnd)}}</text></view><view class="fde-actions"><button class="fde-register" @click="conferenceOpen=true">{{ registrationLabel }} →</button><button class="fde-topic" @click="goFdeTopic">先看 FDE 实战 →</button></view><text class="fde-note">{{registrationLabel === '查看大会报名图' ? '时间和购票以报名图为准。' : '活动开始时间已过，海报仅供回顾，最新活动状态请以官方信息为准。'}}</text></view>
    <view class="fde-poster-wrap"><image class="fde-poster" src="/static/assets/fde-cover.jpg" mode="widthFix" /><text>AI航海家FDE大会 · 活动海报</text></view>
  </view>
</view>
<view class="headline"><view><text class="kicker">同城相聚</text><text class="heading">同城 AI 活动</text></view><text class="muted">{{cities.length}} 个城市 · 已收录的活动</text></view>
<view class="time-filters"><button :class="{on:period==='week'}" @click="period='week';listLimit=12">最近 7 天</button><button :class="{on:period==='all'}" @click="period='all';listLimit=12">全部近期活动</button></view>
<scroll-view scroll-x class="filters"><view class="filter-row"><button :class="{on:!city}" @click="city='';listLimit=12">全部城市</button><button v-for="c in cities" :key="c" :class="{on:city===c}" @click="city=c;listLimit=12">{{c}}</button></view></scroll-view>
<view v-if="!visibleUpcoming.length" class="empty">{{period==='week'?'最近 7 天暂无已收录的 AI 活动，可查看全部近期活动。':'暂无符合条件的近期 AI 活动。'}}</view>
<view v-else class="event-list"><view v-for="item in visibleUpcoming.slice(0,listLimit)" :key="item.id" class="list-event" @click="selected=item"><view class="list-date"><text>{{formatShortDate(item.startTime)}}</text></view><view class="list-main"><view class="list-label">{{item.city}} · {{item.typeText || '同城活动'}} · {{stateLabel(item)}}</view><text class="event-title">{{hideEarningsFigures(item.name)}}</text><text class="event-meta">{{formatDate(item.startTime)}} · {{item.district || item.city}}</text></view><text class="list-more">查看详情 →</text></view><button v-if="visibleUpcoming.length>listLimit" class="more" @click="listLimit+=12">查看更多近期活动</button></view>
<view v-if="visiblePast.length" class="past-section"><button class="past-toggle" :aria-expanded="pastOpen" @click="pastOpen=!pastOpen">{{pastOpen?'收起往期活动及状态待确认':'查看往期活动及状态待确认'}} · {{visiblePast.length}} 场 <text>{{pastOpen?'⌃':'⌄'}}</text></button><view v-if="pastOpen" class="event-list"><view v-for="item in visiblePast.slice(0,pastLimit)" :key="item.id" class="list-event" @click="selected=item"><view class="list-date"><text>{{formatShortDate(item.startTime)}}</text></view><view class="list-main"><view class="list-label">{{item.city}} · {{stateLabel(item)}}</view><text class="event-title">{{hideEarningsFigures(item.name)}}</text><text class="event-meta">{{formatDate(item.startTime)}} · {{item.district || item.city}}</text></view><text class="list-more">查看详情 →</text></view><button v-if="visiblePast.length>pastLimit" class="more" @click="pastLimit+=12">查看更多往期活动</button></view></view>
</view><CampFooter from="events"/><view v-if="conferenceOpen" class="overlay" @click="conferenceOpen=false"><view class="modal conference-modal" @click.stop><view class="modal-top conference-modal-top"><text>线下大会报名资料</text><button class="conference-close" aria-label="关闭大会报名资料" @click="conferenceOpen=false">关闭 ✕</button></view><scroll-view scroll-y class="conference-scroll"><text class="conference-modal-title">查看完整大会报名图</text><text class="conference-modal-copy">{{ conferenceStatus }}。{{registrationLabel === '查看大会报名图' ? '二维码在图片底部，长按识别。' : '此为历史海报，二维码可能已失效，请勿视为当前报名入口。'}}</text><image class="conference-image" src="/static/assets/fde-conference-full.jpg" mode="widthFix" /><text v-if="registrationLabel === '查看大会报名图'" class="conference-qr-label">报名二维码放大 · 手机可长按识别</text><view v-if="registrationLabel === '查看大会报名图'" class="conference-qr-detail"><image class="conference-qr-source" src="/static/assets/fde-conference-full.jpg" mode="widthFix" /></view></scroll-view></view></view><view v-if="selected" class="overlay" @click="selected=null"><view class="modal" @click.stop><view class="modal-top"><text>活动资料 · {{stateLabel(selected)}}</text><text @click="selected=null">关闭 ✕</text></view><text class="modal-title">{{hideEarningsFigures(selected.name)}}</text><text class="event-meta">{{formatDate(selected.startTime)}} · {{selected.city}} {{selected.district}}</text><view class="body"><text v-for="(paragraph,index) in descriptionParagraphs" :key="index" class="description-paragraph">{{hideEarningsFigures(paragraph)}}</text></view><view class="reviews"><text class="column-title">本场活动反馈</text><view v-for="r in selectedReviews" :key="r.sourceId" class="review"><text>{{r.author}} · {{r.attribution}}</text><text>{{hideEarningsFigures(r.text)}}</text></view><text v-if="!selectedReviews.length" class="muted">暂未收录能确认属于本场的评价。</text></view><text class="source-hint">{{selected.url ? '报名方式和群二维码在生财有术活动页，圈友登录后可见。' : '暂未收录本场报名入口，可联系站长咨询。'}}</text><view class="detail-actions"><button class="action" @click="goCamp">{{selected.url ? '查看报名方式 ↗' : '了解体验营及联系站长 →'}}</button><button class="save-event" @click="toggleSave(selected)">{{isSaved(selected) ? '★ 已收藏' : '☆ 收藏活动'}}</button></view></view></view><SiteFooter /></view></view></view>
</template>
<script setup>
import {tutorialFirst} from '../../site-mode.js';
import TutorialOnlyGate from '../../components/TutorialOnlyGate.vue';
import SiteFooter from '../../components/SiteFooter.vue';
import {computed,ref,onUnmounted} from 'vue';
import {onLoad} from '@dcloudio/uni-app';
import SiteHeader from '../../components/SiteHeader.vue';
import CampFooter from '../../components/CampFooter.vue';
import {events,eventReviews} from '../../data/content.js';
import {hideEarningsFigures} from '../../data/case-library.mjs';
import {getSaved,setSaved} from '../../data/storage.js';
const city=ref(''),selected=ref(null),saved=ref(getSaved()),conferenceOpen=ref(false),fdeOpen=ref(false),now=ref(Date.now()),period=ref('week'),listLimit=ref(12),pastLimit=ref(12),pastOpen=ref(false);
const conference=computed(()=>events.find(e=>String(e?.id)==='10533')||null);
const conferenceLabel=computed(()=>{const e=conference.value;if(!e||/CANCEL|ENDED|FINISHED|COMPLETED/i.test(e.lifecycleStatus||'')||(Number(e.startTime)>0&&Number(e.startTime)*1000<=now.value))return '活动资料';return '本期关注'});
const conferenceStatus=computed(()=>{const e=conference.value;if(!e)return '报名状态以活动入口说明为准';if(/CANCEL/i.test(e.lifecycleStatus||''))return '活动已取消';if(/ENDED|FINISHED|COMPLETED/i.test(e.lifecycleStatus||''))return '活动已结束';if(Number(e.submitEnd)>0&&Number(e.submitEnd)*1000<now.value)return Number(e.startTime)>0&&Number(e.startTime)*1000<=now.value?'开始时间已过 · 报名已截止':'报名已截止';if(e.full)return '资料显示名额已满';if(Number(e.startTime)>0&&Number(e.startTime)*1000<=now.value)return '活动状态待确认';return '报名与名额以入口实时说明为准'});
const registrationLabel=computed(()=>{const e=conference.value;if(!e||/CANCEL|ENDED|FINISHED|COMPLETED/i.test(e.lifecycleStatus||'')||(Number(e.startTime)>0&&Number(e.startTime)*1000<=now.value)||(Number(e.submitEnd)>0&&Number(e.submitEnd)*1000<now.value)||e.full)return '查看活动资料';return '查看大会报名图'});
const clock=setInterval(()=>{now.value=Date.now()},60000);onUnmounted(()=>clearInterval(clock));
function goFdeTopic(){uni.navigateTo({url:'/pages/topic/index?slug=fde'})}
onLoad(options=>{if(options?.view==='conference'){fdeOpen.value=true;conferenceOpen.value=true}});
const ai=/(?:^|[^a-z])ai(?=$|[^a-z]|ppt|agent|video)|人工智能|智能体|大模型|生成式|AIGC|GPT|Claude|Codex|Gemini|Grok|Cursor|Copilot|OpenAI|DeepSeek|豆包|通义千问|文心一言|(?:^|[^a-z])(?:FDE|Agent|MCP|LLM)(?=$|[^a-z])|workbuddy|seedance|comfyui|minimax/i;
function isAiEvent(e){if(ai.test(`${e.name||''} ${e.typeText||''}`))return true;return /(?:本期|本次|本场|活动|聚会|分享|主题|从).{0,16}(?:AI|人工智能|智能体|大模型|FDE|Agent|MCP)/i.test(String(e.summary||e.description||'').slice(0,300))}
const groups=computed(()=>{const m=new Map();for(const e of events.filter(e=>e&&e.city&&isAiEvent(e)&&!/CANCEL/i.test(e.lifecycleStatus||''))){if(!m.has(e.city))m.set(e.city,[]);m.get(e.city).push(e)}return [...m.entries()].map(([city,items])=>({city,items}));});
const cities=computed(()=>groups.value.map(g=>g.city));
const filteredEvents=computed(()=>groups.value.filter(g=>!city.value||g.city===city.value).flatMap(g=>g.items));
const visibleUpcoming=computed(()=>filteredEvents.value.filter(e=>{const start=Number(e.startTime)*1000;return !pastOrUncertain(e)&&start>=now.value&&(period.value==='all'||start<now.value+7*86400000)}).sort((a,b)=>Number(a.startTime)-Number(b.startTime)));
const visiblePast=computed(()=>filteredEvents.value.filter(pastOrUncertain).sort((a,b)=>Number(b.startTime)-Number(a.startTime)));
const descriptionParagraphs=computed(()=>String(selected.value?.description||selected.value?.summary||'活动具体内容请以原始资料为准。').replace(/([。！？])\s+/g,'$1\n').split(/\n+|(?=[⏰🎯🗓💰👥🚫])/u).map(x=>x.trim()).filter(Boolean));
const selectedReviews=computed(()=>eventReviews.filter(r=>selected.value&&String(r.eventId)===String(selected.value.id)));
function ended(e){return /ENDED|FINISHED|COMPLETED/i.test(e.lifecycleStatus||'')}
function pastOrUncertain(e){return ended(e)||(Number(e.startTime)>0&&Number(e.startTime)*1000<now.value)}
function stateLabel(e){return ended(e)?'已结束':Number(e.startTime)*1000>now.value?'即将开始':'状态待确认'}
function formatShortDate(t){const d=new Date(Number(t)*1000+8*3600000);return Number.isNaN(d.getTime())?'待定':`${d.getUTCMonth()+1}月${d.getUTCDate()}日`}
function formatDate(t){if(!t)return '时间待确认';const d=new Date(Number(t)*1000+8*3600000);if(Number.isNaN(d.getTime()))return '时间待确认';return `${d.getUTCMonth()+1}月${d.getUTCDate()}日 ${String(d.getUTCHours()).padStart(2,'0')}:${String(d.getUTCMinutes()).padStart(2,'0')}（北京时间）`}
function isSaved(e){return saved.value.includes(`event:${e.id}`)}
function toggleSave(e){const k=`event:${e.id}`;saved.value=isSaved(e)?saved.value.filter(x=>x!==k):[...saved.value,k];setSaved(saved.value)}
function goCamp(){const source=String(selected.value?.url||'');selected.value=null;const safe=/^https:\/\/(?:www\.)?scys\.com\//i.test(source)?'&source='+encodeURIComponent(source):'';uni.navigateTo({url:'/pages/camp/index?from=event'+safe})}
</script>
<style scoped>.wrap{max-width:1200px;margin:0 auto;padding:35rpx 28rpx;color:#161A23}.hero{padding:60rpx;background:#161A23;color:#ECEFFE;border-radius:12rpx}.eyebrow,.kicker{display:block;font-size:21rpx;color:#9AA0AC;font-weight:700;letter-spacing:1rpx}.hero-title{display:block;font-size:62rpx;font-weight:750;margin:15rpx 0}.hero-copy,.disclaimer{display:block;color:#E6E8EC;font-size:27rpx;line-height:1.7}.disclaimer{font-size:22rpx;color:#9AA0AC;margin-top:20rpx}.headline{display:flex;justify-content:space-between;align-items:end;margin:48rpx 0 20rpx}.heading,.city-name{display:block;font-size:40rpx;font-weight:700;margin-top:10rpx}.muted{font-size:24rpx;color:#9AA0AC;line-height:1.7}.filters{white-space:nowrap;margin-bottom:20rpx}.filter-row{display:flex;gap:14rpx;width:max-content;min-width:100%}.filter-row button{flex-shrink:0;white-space:nowrap}.filter-row button,.more{font-size:24rpx;background:#F3F4F6;color:#5F6675;margin:0;line-height:2.6;padding:0 24rpx}.filter-row button.on{background:#5F6675;color:white}.city-card{background:#fff;border:1px solid #E6E8EC;border-radius:12rpx;margin:22rpx 0;overflow:hidden}.city-head{display:flex;align-items:end;justify-content:space-between;background:#E6E8EC;padding:27rpx;color:#5F6675;font-size:23rpx}.columns{display:grid;grid-template-columns:1fr 1fr}.column{padding:25rpx;min-width:0}.column+.column{border-left:1px solid #F3F4F6}.column-title{display:block;font-size:27rpx;font-weight:700;color:#5F6675}.event{padding:25rpx 0;border-bottom:1px solid #F3F4F6}.event-top,.event-bottom{display:flex;justify-content:space-between;color:#9AA0AC;font-size:21rpx;gap:10rpx}.event-title,.event-meta{display:block}.event-title{font-size:28rpx;font-weight:700;margin:14rpx 0;color:#5F6675;line-height:1.5}.event-meta{font-size:23rpx;color:#9AA0AC;line-height:1.6}.event-bottom{color:#5F6675;margin-top:22rpx}.more{margin-top:20rpx}.overlay{position:fixed;z-index:99;inset:0;background:#0008;display:flex;align-items:center;justify-content:center;padding:22rpx}.modal{background:white;border-radius:15rpx;padding:35rpx;max-width:800px;width:100%;max-height:80vh;overflow:auto}.modal-top{display:flex;justify-content:space-between;color:#9AA0AC;font-size:22rpx}.modal-title{display:block;font-size:39rpx;font-weight:700;margin:20rpx 0}.body{display:block;white-space:pre-wrap;font-size:26rpx;line-height:1.8;color:#5F6675;margin:25rpx 0}.reviews{padding-top:20rpx;border-top:1px solid #E6E8EC}.review text{display:block;font-size:23rpx;color:#5F6675;line-height:1.7;margin:10rpx 0}.action{background:#5F6675;color:white;margin:25rpx 0 0;font-size:25rpx}.empty{padding:40rpx;color:#9AA0AC}@media(max-width:600px){.hero{padding:35rpx}.hero-title{font-size:44rpx}.columns{grid-template-columns:1fr}.column+.column{border-left:0;border-top:1px solid #F3F4F6}.headline{align-items:start;gap:10rpx;flex-direction:column}}
.fde-feature{overflow:hidden;background:#161A23;color:#ECEFFE;border-radius:10px}.fde-trigger{display:flex;align-items:center;gap:20px;text-align:left;width:100%;padding:18px 24px;margin:0;background:#161A23;border:0;color:inherit;line-height:normal;border-radius:0}.fde-trigger::after{border:0}.fde-thumb{width:70px;height:104px;flex-shrink:0;border-radius:4px}.fde-preview{flex:1;min-width:0}.fde-preview text,.fde-details-copy text,.fde-poster-wrap text{display:block}.fde-kicker,.fde-detail-label{font-size:12px;font-weight:700;color:#9AA0AC}.fde-title{font-size:23px;font-weight:800;line-height:1.3;color:#fff;margin-top:6px}.fde-meta,.fde-teaser{font-size:13px;line-height:1.6;color:#E6E8EC;margin-top:5px}.fde-toggle{border:1px solid #5F6675;padding:10px 14px;border-radius:6px;white-space:nowrap;font-size:13px;font-weight:700;color:#ECEFFE}.fde-toggle text{margin-left:5px}.fde-details{display:grid;grid-template-columns:minmax(0,1fr) 255px;gap:44px;align-items:center;border-top:1px solid #5F6675;padding:40px 45px}.fde-details-copy{min-width:0}.fde-detail-title{font-size:38px;line-height:1.25;color:#fff;font-weight:800;margin:13px 0}.fde-body{font-size:15px;line-height:1.9;color:#E6E8EC;max-width:650px}.fde-highlights{font-size:13px;font-weight:700;color:#E6E8EC;margin-top:16px}.fde-program{font-size:13px;color:#E6E8EC;margin-top:11px}.fde-info{display:flex;flex-wrap:wrap;gap:8px 18px;margin-top:18px;color:#E6E8EC;font-size:13px;line-height:1.6}.fde-actions{display:flex;flex-wrap:wrap;gap:12px;margin-top:22px}.fde-register,.fde-topic{margin:0;padding:0 18px;line-height:43px;font-size:13px;font-weight:700;border-radius:6px}.fde-register{background:#2B44E6;color:#fff}.fde-topic{background:transparent;color:#E6E8EC;border:1px solid #5F6675}.fde-register::after,.fde-topic::after{border:0}.fde-note{font-size:11px;line-height:1.7;color:#9AA0AC;margin-top:14px}.fde-poster-wrap{width:100%;max-width:255px}.fde-poster{display:block;width:100%;border-radius:6px}.fde-poster-wrap text{font-size:11px;color:#9AA0AC;margin-top:7px}.fde-trigger:focus-visible,.fde-register:focus-visible,.fde-topic:focus-visible{outline:2px solid #FFC83D;outline-offset:-3px}@media(max-width:700px){.fde-trigger{padding:16px;gap:13px;flex-wrap:wrap}.fde-thumb{width:55px;height:82px}.fde-kicker{font-size:11px}.fde-title{font-size:18px}.fde-meta,.fde-teaser{font-size:12px}.fde-toggle{margin-left:68px;padding:8px 12px}.fde-details{grid-template-columns:1fr;gap:25px;padding:24px 20px}.fde-detail-title{font-size:29px}.fde-poster-wrap{max-width:190px}.fde-info{display:block}.fde-info text{margin-top:6px}}
.columns.has-empty{grid-template-columns:1fr}.columns.has-empty .column+.column{border-left:0;border-top:1px solid #F3F4F6}.column.is-empty{display:flex;align-items:center;gap:14px;padding:14px 18px}.column.is-empty .column-title,.column.is-empty .muted{font-size:12px}.conference-card{display:flex;align-items:center;justify-content:space-between;gap:20rpx;background:#fffaf1;border:1px solid #efdfbe;border-radius:12rpx;padding:30rpx;margin-top:24rpx}.conference-card-copy text{display:block}.conference-label{color:#2B44E6;font-size:21rpx;font-weight:700}.conference-title{font-size:31rpx;font-weight:750;color:#161A23;margin-top:8rpx}.conference-subtitle{font-size:22rpx;color:#5F6675;margin-top:8rpx;line-height:1.5}.conference-cta{font-size:23rpx;font-weight:700;color:#2B44E6;white-space:nowrap}.conference-modal{max-width:500px;max-height:min(90vh,900px);box-sizing:border-box;display:flex;flex-direction:column;overflow:hidden}.conference-modal-top{flex:none;align-items:center;padding-bottom:10px}.conference-close{margin:0;padding:0 8px;background:transparent;color:#5F6675;font-size:13px;line-height:34px}.conference-close:after{border:0}.conference-scroll{min-height:0;flex:1;overflow-y:auto;-webkit-overflow-scrolling:touch;overscroll-behavior:contain}.conference-modal-title,.conference-modal-copy,.conference-image-tip{display:block}.conference-modal-title{font-size:36rpx;font-weight:750;margin:20rpx 0 12rpx}.conference-modal-copy,.conference-image-tip{font-size:23rpx;line-height:1.7;color:#5F6675}.conference-image{width:100%;margin-top:18rpx;display:block}.conference-image-tip{text-align:center;margin-top:8rpx}.conference-qr-label{display:block;text-align:center;font-size:13px;font-weight:700;color:#5F6675;margin:20px 0 10px}.conference-qr-detail{position:relative;overflow:hidden;width:250px;height:250px;max-width:100%;margin:0 auto 14px;background:#00131d;border-radius:8px}.conference-qr-source{position:absolute;display:block;width:750px;max-width:none;left:-245px;top:-12655px}.conference-button{margin:20rpx 0 0;background:#2B44E6;color:#fff;font-size:25rpx}.conference-button:after{border:0}
